import cn.lgs.knowledgebase.infrastructure.persistence.JdbcIngestionRepository;
import cn.lgs.knowledgebase.application.raw.*;
import cn.lgs.knowledgebase.domain.ingestion.IngestionDomain.ProgressStage;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.transaction.support.TransactionTemplate;
import java.nio.file.*;import java.sql.Timestamp;import java.time.*;import java.util.*;

/** A real full 600-second DB stage, without forced clock/deadline or model work. */
public class RawActualStageDeadlineProbe {
  public static void main(String[] args)throws Exception {
    var db=new JdbcTemplate(new DriverManagerDataSource(System.getenv("PROBE_JDBC_URL"),"evokb_target",System.getenv("PROBE_DB_PASSWORD")));var repo=new JdbcIngestionRepository(db,new TransactionTemplate(new DataSourceTransactionManager(db.getDataSource())),new ObjectMapper());String file=UUID.randomUUID().toString(),batch=UUID.randomUUID().toString();db.update("INSERT INTO ingestion_batch(batch_id,created_by_username,source_count) VALUES(?,'actual600-synthetic-source',1)",batch);db.update("INSERT INTO ingestion_file(file_id,batch_id,relative_path,original_filename,staging_path,sha256,logical_name) VALUES(?,?,'fixture','fixture','fixture','fixture','fixture')",file,batch);repo.queueBatch(batch,Instant.now());var claim=repo.claimRaw(file,UUID.randomUUID().toString()).orElseThrow();var execution=repo.rawExecution(claim);execution.phase(ProgressStage.PARSING);Timestamp deadline=db.queryForObject("SELECT stage_deadline FROM ingestion_file WHERE file_id=?",Timestamp.class,file);Timestamp start=db.queryForObject("SELECT stage_started_at FROM ingestion_file WHERE file_id=?",Timestamp.class,file);ObjectMapper json=new ObjectMapper();var samples=new ArrayList<Object>();Map<String,Object> report=new LinkedHashMap<>();report.put("status","RUNNING_ACTUAL_RAW_DB600");report.put("fileId",file);report.put("stageStartedAt",start.toInstant().toString());report.put("stageDeadline",deadline.toInstant().toString());report.put("samples",samples);report.put("boundary","Actual600-second PostgreSQL ownership/stage wait; explicit synthetic source task. No parsing/inference/browser/application workflow is running, and no DB deadline/clock fault injection.");boolean preserved=true;
    while(true){Timestamp now=db.queryForObject("SELECT clock_timestamp()",Timestamp.class);double elapsed=Duration.between(start.toInstant(),now.toInstant()).toMillis()/1000d;if(!now.before(deadline))break;execution.phase(ProgressStage.PARSING);repo.resetInterrupted(Instant.now());preserved&=deadline.equals(db.queryForObject("SELECT stage_deadline FROM ingestion_file WHERE file_id=? AND status='RUNNING'",Timestamp.class,file));samples.add(Map.of("databaseNow",now.toInstant().toString(),"elapsedSeconds",elapsed,"deadlineUnchanged",preserved));json.writerWithDefaultPrettyPrinter().writeValue(Path.of(args[0]).toFile(),report);Thread.sleep(Math.min(15000,Math.max(1,deadline.getTime()-now.getTime())));}
    boolean denied=false;try{execution.fenced(()->db.update("UPDATE ingestion_file SET error_message='MUST NOT WRITE' WHERE file_id=?",file));}catch(IllegalStateException expected){denied=true;}repo.resetInterrupted(Instant.now());var replacement=repo.claimRaw(file,UUID.randomUUID().toString()).orElseThrow();var checks=new LinkedHashMap<String,Object>();checks.put("fixedStageBudgetExactly600",Duration.between(start.toInstant(),deadline.toInstant()).toMillis()>=599990&&Duration.between(start.toInstant(),deadline.toInstant()).toMillis()<=600010);checks.put("repeatedStagesAndScannerNeverRenewed",preserved);checks.put("actuallyWaitedAtLeast600",Duration.between(start.toInstant(),db.queryForObject("SELECT clock_timestamp()",Timestamp.class).toInstant()).toMillis()>=600000);checks.put("lateOldOwnerCannotWriteAfterRealDeadline",denied&&db.queryForObject("SELECT count(*) FROM ingestion_file WHERE file_id=? AND error_message='MUST NOT WRITE'",Long.class,file)==0);checks.put("realExpiredRecoveryCreatesSecondEpoch",replacement.epoch()==2&&db.queryForObject("SELECT count(*) FROM raw_ingestion_failure WHERE file_id=? AND error_code='RAW_STAGE_EXPIRED'",Long.class,file)==1);report.put("checks",checks);report.put("status",checks.values().stream().allMatch(Boolean.TRUE::equals)?"PASS_ACTUAL_RAW_DB600":"FAIL_ACTUAL_RAW_DB600");report.put("finishedAt",Instant.now().toString());json.writerWithDefaultPrettyPrinter().writeValue(Path.of(args[0]).toFile(),report);if(checks.values().stream().anyMatch(v->!Boolean.TRUE.equals(v)))System.exit(1);
  }
}
